"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Second backbone (docs/evaluation_protocol.md, section 17; approved by the author 2026-11-24): Voxtral Mini 3B in
VoxTurn's place, with the first backbone's frozen recipe (scripts/p1v4_l1.py) unchanged.

Voxtral (mistralai/Voxtral-Mini-3B-2507, revision 3060fe3): Whisper-large-v3 encoder (1280-d, 50 frames per second)
-> projector (4 frames stacked, 5120 -> 3072 -> 3072; 12.5 audio tokens per second) -> Ministral 3B (Llama, 30
layers, 3072-d). What differs from the first backbone is interface only (docs/evaluation_protocol.md, section 17):
  - input format, Voxtral's own: <s>[INST][BEGIN_AUDIO] + audio tokens + text (no closing audio token). The window is
    padded to 30 s as Voxtral's processor pads every input (375 audio tokens; the 8 s window is the first 100);
  - log-mel: Whisper's 128-bin log-mel (as VoxTurn's LogMel) on the window padded to 30 s, on the GPU; checked against
    Voxtral's own feature extractor (command check);
  - option head: Voxtral has none, so the new head (hidden -> 1, as VoxTurn's) starts at zero (both options 0.5);
  - the new LoRA adapter (r 16, alpha 32, every linear layer of the language model) is the only adapter;
  - attention: scaled-dot-product (VoxTurn ran eager); the block-isolating mask goes in as a 4-D boolean mask
    (checked: one pass with both questions = two single-question passes).
Everything else is p1v4_l1's: questions and phrasings, the situation text (the most recent 1,024 tokens) and the
speaking-state marker, training (2 epochs, micro-batch 1 x 8, AdamW 1e-4 without weight decay, 300 warm-up steps then
linear decay, clipping 1.0, bf16 autocast, phrasing drawn per sample) and the epoch choice on dev
(p1v4_score.operating_point: floors met, then the five-part mean).

The situation texts need the laptop's front-end features, so `prep` writes them once (data/p1v4/runs_bb2/examples_*);
the GPU machine reads those files and the windows (stored there as lossless FLAC, read as the same samples).
usage (repo root):
  python -X utf8 scripts/bb2_voxtral.py prep                       laptop: examples and dev rows -> data/p1v4/runs_bb2/
  python -X utf8 scripts/bb2_voxtral.py check [n]                  CPU, fp32: log-mel, native forward, isolating mask
  python -X utf8 scripts/bb2_voxtral.py train <out_dir> [--limit N] GPU; --limit: the first N shuffled training windows
                                                                   and N dev windows (the trial: memory and speed)
  python -X utf8 scripts/bb2_voxtral.py score <out_dir> dev        GPU: scores_dev.json with the kept checkpoint
"""
import json
import os
import random
import sys
import time
from types import SimpleNamespace

import numpy as np
import soundfile as sf
import torch
import torch.nn as nn
import torch.nn.functional as F

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_l1 as L1  # noqa: E402
import p1v4_score as S  # noqa: E402

VOXTRAL_DIR = "data/models_dl/voxtral_mini_3b_3060fe3"
RUNS = "data/p1v4/runs_bb2"
SR = 16000
N_30S = 30 * SR
WIN = 8 * SR
BOS, INST, BEGIN_AUDIO, AUDIO = 1, 3, 25, 24
MOD = SimpleNamespace(LEN_BUCKET=64)


class LogMel(nn.Module):
    """Whisper's log-mel (128 bins, 25 ms / 10 ms; = VoxTurn's LogMel) of the window right-padded to 30 s with zeros,
    as Voxtral's feature extractor pads: (B, 128000) -> (B, 128, 3000)."""

    def __init__(self, fe):
        super().__init__()
        self.register_buffer("filters", torch.tensor(fe.mel_filters.T, dtype=torch.float32), persistent=False)
        self.register_buffer("window", torch.hann_window(400), persistent=False)

    def forward(self, x):
        x = F.pad(x.float(), (0, N_30S - x.shape[1]))
        spec = torch.stft(x, 400, 160, window=self.window, return_complex=True)[..., :-1].abs() ** 2
        mel = (self.filters @ spec).clamp(min=1e-10).log10()
        mel = torch.maximum(mel, mel.amax(dim=(1, 2), keepdim=True) - 8.0)
        return (mel + 4.0) / 4.0


class VoxtralVT(nn.Module):
    """Voxtral behind the interface p1v4_l1.L1v4 and p1v4_readout.forward_states use (VoxTurn's): mel, encode_audio,
    llm, tok, seq_head / audio_open / audio_close, context_ids, prompt, isolating_mask, head, questions."""

    def __init__(self, path=VOXTRAL_DIR, dtype=torch.bfloat16, full=None):
        super().__init__()
        from transformers import AutoTokenizer, VoxtralForConditionalGeneration, WhisperFeatureExtractor
        if full is None:
            full = VoxtralForConditionalGeneration.from_pretrained(path, dtype=dtype, attn_implementation="sdpa")
        base = full.model
        self.encoder = base.audio_tower.requires_grad_(False).eval()
        self.adapter = base.multi_modal_projector.requires_grad_(False).eval()
        self.llm = base.language_model.requires_grad_(False)
        self.stack = full.config.audio_config.intermediate_size                   # 5120 = 4 frames x 1280
        self.hidden = full.config.text_config.hidden_size
        del full
        self.mel = LogMel(WhisperFeatureExtractor.from_pretrained(path))
        self.tok = AutoTokenizer.from_pretrained(path, fix_mistral_regex=True)
        self.seq_head, self.audio_open, self.audio_close = [BOS, INST], [BEGIN_AUDIO], []
        self.head = nn.Linear(self.hidden, 1)
        nn.init.zeros_(self.head.weight)
        nn.init.zeros_(self.head.bias)
        self.questions = {}
        self._prompts = {}

    def encode_audio(self, mel):
        """Log-mel (B, 128, 3000) -> audio tokens (B, 375, 3072) as the language model reads them (Voxtral's
        get_audio_features per window; the first 100 tokens are the 8 s window)."""
        with torch.no_grad():
            h = self.encoder(mel.to(self.encoder.conv1.weight.dtype)).last_hidden_state      # (B, 1500, 1280)
            a = self.adapter(h.reshape(h.shape[0], -1, self.stack))                         # (B, 375, 3072)
        return a.to(self.llm.get_input_embeddings().weight.dtype)

    def ids(self, text):
        return self.tok(text, add_special_tokens=False).input_ids

    def prompt(self, task, lang, k=0):
        """= VoxTurn.prompt: question ids and each option's last-token index within them."""
        key = (task, lang, k)
        if key not in self._prompts:
            q = self.questions[task]
            ids = self.ids("\nQuestion: {}\nOptions:".format(q["phrasings"][lang][k]))
            pos = []
            for lab in q["labels"]:
                ids += self.ids(f" {q['options'][lang][lab]}")
                pos.append(len(ids) - 1)
            self._prompts[key] = (ids, pos)
        return self._prompts[key]

    def context_ids(self, text, speaker, lang, max_tokens):
        """= VoxTurn.context_ids (English markers)."""
        ids = self.ids("\n" + text)[-max_tokens:] if text else []
        marker = {"user": "\n[User is speaking]", "agent": "\n[Agent is speaking]"}[speaker]
        return ids + self.ids(marker)

    @staticmethod
    def isolating_mask(blocks, L, dev):
        """= VoxTurn.isolating_mask: causal; each question block sees only the prefix and itself."""
        Sn = len(blocks)
        allow = torch.ones(L, L, dtype=torch.bool, device=dev).tril().repeat(Sn, 1, 1)
        pos = torch.arange(L, device=dev).repeat(Sn, 1)
        for s, spans in enumerate(blocks):
            p0 = spans[0][0]
            for a, n in spans:
                allow[s, a:a + n, p0:a] = False
                pos[s, a:a + n] = torch.arange(p0, p0 + n, device=dev)
        return {"attention_mask": allow[:, None], "position_ids": pos}


class L1vx(L1.L1v4):
    """p1v4_l1.L1v4 on Voxtral: the same forward (inherited); built with the new adapter as the only adapter."""

    def __init__(self, mod, vt, lora_r=16):
        nn.Module.__init__(self)
        from peft import LoraConfig, get_peft_model
        from peft.tuners.tuners_utils import BaseTunerLayer
        self.mod, self.vt = mod, vt
        vt.questions = dict(L1.QUESTIONS)
        vt.llm = get_peft_model(vt.llm, LoraConfig(r=lora_r, lora_alpha=2 * lora_r, lora_dropout=0.0,
                                                   target_modules="all-linear"), adapter_name=L1.NEW)
        for m in vt.llm.modules():
            if isinstance(m, BaseTunerLayer):
                m.cast_input_dtype_enabled = False
        self.new_head = nn.Linear(vt.head.in_features, 1).to(vt.head.weight.device)
        with torch.no_grad():
            self.new_head.weight.copy_(vt.head.weight)
            self.new_head.bias.copy_(vt.head.bias)
        for n, p in vt.named_parameters():
            p.requires_grad_(f".{L1.NEW}." in n)


def build(device="cuda", dtype=torch.bfloat16, full=None):
    vt = VoxtralVT(dtype=dtype, full=full)
    model = L1vx(MOD, vt).to(device)
    vt.llm.eval()
    return model


# ------------------------------------------------------------------------------------------------ data

def prep():
    """Laptop: the training and dev examples exactly as p1v4_l1.examples builds them, and the dev rows."""
    os.makedirs(RUNS, exist_ok=True)
    for which in ("train", "dev"):
        ex, rows = L1.examples(which)
        json.dump([dict(e, id=list(e["id"])) for e in ex], open(f"{RUNS}/examples_{which}.json", "w"))
        if which == "dev":
            json.dump(rows, open(f"{RUNS}/rows_dev.json", "w"))
        print(f"{which}: {len(ex)} windows, {sum(len(e['qs']) for e in ex)} questions", flush=True)


def local_path(p):
    """The GPU machine holds the windows as FLAC packed from the laptop's current files (lossless; the same
    samples); the FLAC is preferred over any older WAV copy there."""
    f = p[:-4] + ".flac"
    if p.endswith(".wav") and os.path.exists(f):
        return f
    if os.path.exists(p):
        return p
    raise FileNotFoundError(p)


def load_examples(which):
    ex = json.load(open(f"{RUNS}/examples_{which}.json"))
    for e in ex:
        e["id"] = tuple(e["id"])
        e["qs"] = [tuple(q) for q in e["qs"]]
        e["path"] = local_path(e["path"])
    return ex


def card():
    free, total = torch.cuda.mem_get_info()
    return (f"peak {torch.cuda.max_memory_allocated() / 2**30:.2f} GB, reserved "
            f"{torch.cuda.memory_reserved() / 2**30:.2f} GB, card free {free / 2**30:.2f} of {total / 2**30:.2f} GB")


# ------------------------------------------------------------------------------------------------ train, score

def train(out_dir, limit=None):
    """= p1v4_l1.train with the Voxtral model; limit N (the trial): N training windows, N dev windows, timings."""
    os.makedirs(out_dir, exist_ok=True)
    torch.manual_seed(0)
    rng = random.Random(0)
    tr = [e for e in load_examples("train") if any(y is not None for _, y in e["qs"])]
    dv = load_examples("dev")
    dv_rows = json.load(open(f"{RUNS}/rows_dev.json"))
    if limit:
        tr = [tr[i] for i in random.Random(1).sample(range(len(tr)), limit)]
        dv = dv[:limit]
    print(f"train windows {len(tr)}, dev windows {len(dv)}", flush=True)
    t_load = time.time()
    model = build()
    print(f"model built in {time.time() - t_load:.0f} s; {card()}", flush=True)
    params = model.trainable_parameters()
    print(f"trainable parameters {sum(p.numel() for p in params) / 1e6:.2f} M", flush=True)
    opt = torch.optim.AdamW(params, lr=L1.LR, weight_decay=0.0)
    lens = [len(model.vt.tok("\n" + e["text"], add_special_tokens=False).input_ids) for e in tr]
    j = int(np.argmax(lens))                                # memory check on the longest training window, no update
    torch.cuda.reset_peak_memory_stats()
    lg = L1.run(model, tr, torch.from_numpy(sf.read(tr[j]["path"], dtype="float32")[0])[None].cuda(), [j], [0])
    F.cross_entropy(lg, torch.tensor([-100 if y is None else y for _, y in tr[j]["qs"]], device="cuda"),
                    ignore_index=-100).backward()
    opt.zero_grad(set_to_none=True)
    del lg
    print(f"longest training text {lens[j]} tokens (median {int(np.median(lens))}): fits; {card()}", flush=True)
    torch.cuda.empty_cache()
    torch.cuda.reset_peak_memory_stats()
    steps = L1.EPOCHS * (len(tr) // (L1.MICRO * L1.ACCUM))
    sched = torch.optim.lr_scheduler.LambdaLR(opt, lambda s: min((s + 1) / L1.WARMUP, max(0.0, (steps - s) / steps)))
    log, best, step, micro = [], None, 0, 0
    every = 1 if limit else 200
    opt.zero_grad(set_to_none=True)
    for ep in range(L1.EPOCHS):
        t0, run_loss = time.time(), []
        for w, idx in L1.loader(tr, True, L1.MICRO, seed=ep):
            idx = idx.tolist()
            logits = L1.run(model, tr, w.cuda(non_blocking=True), idx,
                            [rng.randrange(L1.N_PHRASINGS) for _ in idx])
            ys = torch.tensor([-100 if y is None else y for i in idx for _, y in tr[i]["qs"]], device="cuda")
            loss = F.cross_entropy(logits, ys, ignore_index=-100)
            (loss / L1.ACCUM).backward()
            run_loss.append(loss.item())
            micro += 1
            if micro % L1.ACCUM:
                continue
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()
            sched.step()
            opt.zero_grad(set_to_none=True)
            step += 1
            if step % every == 0:
                print(f"ep {ep} step {step}/{steps} loss {np.mean(run_loss[-400:]):.4f} "
                      f"{L1.ACCUM * (time.time() - t0) / len(run_loss):.3f} s/step {card()}", flush=True)
        t_train = time.time() - t0
        torch.cuda.empty_cache()
        t1 = time.time()
        sc = L1.score(model, dv)
        t_score = time.time() - t1
        torch.cuda.empty_cache()
        res = S.operating_point(dv_rows, sc) if not limit else {}
        res.update(epoch=ep, train_loss=float(np.mean(run_loss)), minutes=round((time.time() - t0) / 60, 1),
                   s_per_train_window=round(t_train / len(tr), 4), s_per_dev_window=round(t_score / len(dv), 4))
        log.append(res)
        print(json.dumps(res), flush=True)
        if limit:
            n_full = len([e for e in load_examples("train") if any(y is not None for _, y in e["qs"])])
            n_dev = len(load_examples("dev"))
            est = L1.EPOCHS * (n_full * res["s_per_train_window"] + n_dev * res["s_per_dev_window"]) / 3600
            print(f"trial estimate for the full run ({n_full} training, {n_dev} dev windows, {L1.EPOCHS} epochs): "
                  f"{est:.1f} h; {card()}", flush=True)
            json.dump(log, open(os.path.join(out_dir, "trial_log.json"), "w"), indent=1)
            return
        if best is None or L1.rank(res) > L1.rank(best):
            best = res
            torch.save(L1.new_state(model), os.path.join(out_dir, "l1_new.pt"))
            L1.save_scores(sc, os.path.join(out_dir, "scores_dev.json"))
        json.dump(log, open(os.path.join(out_dir, "train_log.json"), "w"), indent=1)
    print("kept epoch", best["epoch"], json.dumps(best))


def score_cmd(out_dir, which):
    ex = load_examples(which)
    model = build()
    L1.load_new_state(model, torch.load(os.path.join(out_dir, "l1_new.pt"), weights_only=True))
    sc = L1.score(model, ex)
    L1.save_scores(sc, os.path.join(out_dir, f"scores_{which}.json"))
    if which == "dev":
        print(json.dumps(S.operating_point(json.load(open(f"{RUNS}/rows_dev.json")), sc)))


# ------------------------------------------------------------------------------------------------ check (CPU)

def check(n=2):
    """CPU, fp32, one copy of the weights. (1) LogMel = Voxtral's feature extractor; (2) Voxtral's own forward ([AUDIO]
    placeholders, the extractor's features; run before the adapter is added) = the hand-built sequence through
    L1v4.forward with the new adapter added (B = 0, so no effect yet), at the option positions; (3) one pass with both
    questions = two single-question passes, at the option positions the head reads."""
    from transformers import VoxtralForConditionalGeneration, WhisperFeatureExtractor
    torch.manual_seed(0)
    ex = [e for e in load_examples("dev") if len(e["qs"]) == 2][:n]
    fe = WhisperFeatureExtractor.from_pretrained(VOXTRAL_DIR)
    waves = torch.stack([torch.from_numpy(sf.read(e["path"], dtype="float32")[0]) for e in ex])
    mel_ours = LogMel(fe)(waves)
    mel_ref = fe([w.numpy() for w in waves], sampling_rate=SR, return_tensors="pt").input_features
    d_mel = float((mel_ours - mel_ref).abs().max())
    print(f"(1) log-mel {tuple(mel_ours.shape)} vs extractor {tuple(mel_ref.shape)}: max |diff| {d_mel:.2e}", flush=True)
    full = VoxtralForConditionalGeneration.from_pretrained(VOXTRAL_DIR, dtype=torch.float32,
                                                           attn_implementation="sdpa").eval()
    tok_vt = VoxtralVT.__new__(VoxtralVT)                     # tokenizer helpers only, for the reference ids
    nn.Module.__init__(tok_vt)
    from transformers import AutoTokenizer
    tok_vt.tok = AutoTokenizer.from_pretrained(VOXTRAL_DIR, fix_mistral_regex=True)
    tok_vt.questions, tok_vt._prompts = dict(L1.QUESTIONS), {}
    refs = []
    t0 = time.time()
    with torch.no_grad():
        for b, e in enumerate(ex):
            ctx = VoxtralVT.context_ids(tok_vt, e["text"], e["marker"], "en", L1.MAX_TEXT_TOKENS)
            q_ids, q_pos = VoxtralVT.prompt(tok_vt, e["qs"][0][0], "en", 0)
            ids = [BOS, INST, BEGIN_AUDIO] + [AUDIO] * 375 + ctx + q_ids
            h = full.model(input_ids=torch.tensor([ids]), input_features=mel_ref[b:b + 1]).last_hidden_state[0]
            pos = [len(ids) - len(q_ids) + p for p in q_pos]
            refs.append((len(ids), pos, h[pos].clone()))
    print(f"reference forwards {time.time() - t0:.0f} s", flush=True)
    model = build(device="cpu", dtype=torch.float32, full=full)
    model.eval()
    vt = model.vt
    res = {"mel_max_abs_diff": d_mel}

    def states(b, qs):
        got = {}
        hk = vt.llm.register_forward_hook(lambda m, a, o: got.__setitem__("h", o.last_hidden_state))
        lg = model(waves[b:b + 1], [ex[b]["text"]], [ex[b]["marker"]], [[(t, 0) for t in qs]])
        hk.remove()
        return got["h"][0], lg

    with torch.no_grad():
        for b, e in enumerate(ex):
            n_tok, pos, ref = refs[b]
            ta, tb = e["qs"][0][0], e["qs"][1][0]
            ha, lg_a = states(b, [ta])
            d_h = float((ha[pos] - ref).abs().max())
            rel = d_h / float(ref.abs().max())
            print(f"(2) window {b}: {n_tok} tokens; option states ours vs Voxtral's forward max |diff| {d_h:.2e} "
                  f"(relative {rel:.1e}); new head logits at the start {lg_a.tolist()}", flush=True)
            hb_, _ = states(b, [tb])
            hboth, _ = states(b, [ta, tb])
            pre = n_tok - len(vt.prompt(ta, "en", 0)[0])
            qa, qb = vt.prompt(ta, "en", 0), vt.prompt(tb, "en", 0)
            d_a = float((hboth[[pre + p for p in qa[1]]] - ha[[pre + p for p in qa[1]]]).abs().max())
            d_b = float((hboth[[pre + len(qa[0]) + p for p in qb[1]]] - hb_[[pre + p for p in qb[1]]]).abs().max())
            print(f"(3) window {b}: both questions in one pass vs single passes, option states max |diff| "
                  f"{d_a:.2e} / {d_b:.2e}", flush=True)
            res[f"window{b}"] = {"tokens": n_tok, "native_max_abs": d_h, "native_rel": rel, "iso_a": d_a,
                                 "iso_b": d_b, "head_logits_start": lg_a.tolist()}
    print(f"done in {time.time() - t0:.0f} s", flush=True)
    os.makedirs(RUNS, exist_ok=True)
    json.dump(res, open(f"{RUNS}/check_cpu.json", "w"), indent=1)


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    if cmd == "prep":
        prep()
    elif cmd == "check":
        check(int(sys.argv[2]) if len(sys.argv) > 2 else 2)
    elif cmd == "train":
        lim = int(sys.argv[sys.argv.index("--limit") + 1]) if "--limit" in sys.argv else None
        train(sys.argv[2], lim)
    elif cmd == "score":
        score_cmd(sys.argv[2], sys.argv[3])
    else:
        raise SystemExit(__doc__)
